<?php require __DIR__.'/inc/bootstrap.php'; $posts=load_json('posts.json');$id=$_GET['id']??'';$post=null;$index=null;foreach($posts as $i=>$p){if((string)$p['id']===(string)$id){$post=$p;$index=$i;break;}}if($post&&$index!==null){$posts[$index]['views']=((int)($post['views']??0))+1;save_json('posts.json',$posts);$post=$posts[$index];}$settings=site_settings(); ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($post['title']??'DATA NOT FOUND')?></title><link rel="stylesheet" href="assets/style.css"></head><body><?php include __DIR__.'/inc/header.php'; ?><main class="container"><article class="card"><?php if($post): ?><div class="post-meta">[ DATA LOG ] <?=e($post['date']??'')?> // VIEWS <?=e($post['views'])?></div><h1><?=e($post['title'])?></h1><?php if(!empty($post['tags'])):?><div class="tags"><?php foreach($post['tags'] as $t):?><a href="index.php?tag=<?=urlencode($t)?>">#<?=e($t)?></a><?php endforeach;?></div><?php endif;?><div class="article-content"><?=nl2br(e($post['content']))?></div><?php else: ?><h1>DATA NOT FOUND</h1><?php endif; ?></article></main><?php include __DIR__.'/inc/footer.php'; ?></body></html>
